    {
      "id": "IR-S1",
      "method": "Copy original ninja_cleanup_probe.py byte-identically to new directory and execute once. Original expected-defect oracle and its exit remain untouched.",
      "acceptance": [
        "source before/after matches frozen helper SHA",
        "original probe records AssertionError timeout at 0.2s",
        "observed original leaf in a separate PGID and owned SID appears in helper snapshot",
        "leaf is absent or Z/X after helper return",
        "no live owned process after independent cleanup",
        "no independent kill required if helper reports complete"
      ],
      "limit": "Original probe exit 1/not-confirmed is expected if defect no longer occurs; do not relabel that raw exit as 0."
    },
    {
      "id": "IR-S2",
      "method": "Create one unrelated own process in a fresh session; use actual pidfd_open and candidate identity reader with forged SID then start_ticks; reject both and verify process remains alive.",
      "acceptance": [
        "both calls return false",
        "unrelated process remains alive after each call",
        "only test-owned unrelated fixture is subsequently terminated and reaped"
      ],
      "limit": "No actual PID reuse is attempted."
    },
    {
      "id": "IR-S3",
      "method": "Deterministic absent-pidfd capability boundary, with real identity read and no signal operations.",
      "acceptance": [
        "cleanup cannot return complete without both required pidfd capabilities"
      ],
      "limit": "No claim about non-Linux full behavior."
    }
  ],
  "execution_budget": "One original 0.2s synthetic run; one short unrelated-session control; no repeated suite or hosted run.",
